#include <QtWidgets>
#include <iostream>
void need(bool b,const char* why){if(!b)throw std::runtime_error(why);}
int main(int argc,char** argv){QApplication app(argc,argv);try{QTemporaryDir d;auto store=std::make_shared<BusinessStore>(d.filePath("business.sqlite"));store->save("trades",{{"accountId","local"},{"instrumentId","SH:stock:600001"},{"name","测试"},{"date","2026-10-01"},{"side","buy"},{"quantity",100},{"price",10.},{"fee",5.},{"tax",0.}});store->save("reports",{{"title","原快照"},{"text","原记录"},{"accountId","local"},{"legacySource","portfolio_snapshots"},{"legacyOriginal",QJsonObject{{"snapshot_date","2026-10-01"},{"cash_balance",1000.},{"total_market_value",2000.},{"total_assets",3000.},{"total_pnl",100.}}}});auto before=store->backup();AccountAnalysisPage page(store,false,[]{return QJsonArray{QJsonObject{{"id","SH:stock:600001"},{"quote",QJsonObject{{"price",11.},{"tradeDate","2026-10-12"},{"source","explicit input"}}}}};});auto table=page.findChild<QTableWidget*>("analysisPositions"),history=page.findChild<QTableWidget*>("analysisHistory");need(table->rowCount()==1&&table->item(0,0)->text()=="SH:stock:600001","identity structure");need(page.findChild<QLabel*>("analysisSummary")->text().contains("输入现金 未知"),"cash missing");need(history->rowCount()==1&&history->item(0,1)->text()=="3000","original history");history->cellClicked(0,0);need(page.findChild<QPlainTextEdit*>("analysisOriginal")->toPlainText().contains("total_assets"),"exact original opened");page.reload();need(store->backup()["accounts"]==before["accounts"]&&store->backup()["trades"]==before["trades"]&&store->backup()["reports"]==before["reports"],"analysis wrote records");AccountAnalysisPage paper(store,true,[] {return QJsonArray{};});need(paper.findChild<QTableWidget*>("analysisPositions")->rowCount()==0,"paper isolation");auto changed=store->read("accounts")[0].toObject();changed["type"]="paper";store->save("accounts",changed);page.reload();need(page.findChild<QLabel*>("analysisSummary")->text().isEmpty()&&history->rowCount()==0&&table->rowCount()==0&&page.findChild<QPlainTextEdit*>("analysisOriginal")->toPlainText().isEmpty(),"no-account clears stale results");std::cout<<"account page: structure, missing cash, original history selection, reload read-only and paper isolation GREEN\n";}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}return 0;}
